// Имена компонентов Jinx UI взяты по общепринятой конвенции пакета (@jinx-ui/react);
// при расхождении с вашей версией достаточно поправить импорт.
import { useId, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  Select,
  SelectOption,
  Stack,
  Switch,
  TextField,
} from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLES: { value: Role; label: string }[] = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const formId = useId();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const showError = touched && !isValid;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
    setRole('viewer');
    setNotify(true);
  };

  return (
    <Stack direction="column" gap="var(--jx-space-4)">
      {invitedEmail && (
        <Alert
          status="success"
          title="Приглашение отправлено"
          closable
          onClose={() => setInvitedEmail(null)}
        >
          Мы отправили приглашение на {invitedEmail}.
        </Alert>
      )}

      <Card>
        <form onSubmit={handleSubmit} noValidate>
          <Stack direction="column" gap="var(--jx-space-4)">
            <TextField
              id={`${formId}-email`}
              type="email"
              name="email"
              label="Электронная почта"
              placeholder="name@company.com"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              onBlur={() => setTouched(true)}
              invalid={showError}
              helperText={
                showError
                  ? 'Введите адрес в формате name@company.com'
                  : 'Участник получит доступ к проектам команды.'
              }
              required
            />

            <Select
              id={`${formId}-role`}
              name="role"
              label="Роль"
              value={role}
              onChange={(value: Role) => setRole(value)}
            >
              {ROLES.map((item) => (
                <SelectOption key={item.value} value={item.value}>
                  {item.label}
                </SelectOption>
              ))}
            </Select>

            <Switch
              id={`${formId}-notify`}
              name="notify"
              label="Отправить уведомление"
              checked={notify}
              onChange={(checked: boolean) => setNotify(checked)}
            />

            <Button type="submit" variant="primary" disabled={!isValid}>
              Отправить приглашение
            </Button>
          </Stack>
        </form>
      </Card>
    </Stack>
  );
}

